// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFile 是每个仓库低库存阈值的配置文件，按 `config/<用途>.json` 约定放在 config/ 下。
// 它是变量，方便测试替换成 fixture。
var thresholdsFile = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值：配置了就用配置值，没配回退默认值。
func LowStockThreshold(warehouse string) int {
	thresholds, ok := readThresholds()
	if !ok {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// readThresholds 读取阈值配置。文件不存在、读不出来、内容不是 JSON 对象时，ok 都为 false。
func readThresholds() (map[string]int, bool) {
	data, err := os.ReadFile(findThresholdsFile())
	if err != nil {
		return nil, false
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, false
	}
	if thresholds == nil {
		return nil, false
	}
	return thresholds, true
}

// findThresholdsFile 解析配置文件位置：绝对路径直接用；相对路径从当前目录向上找，
// 这样从仓库根运行和从包目录（go test）运行都能找到同一份 config/。
func findThresholdsFile() string {
	if filepath.IsAbs(thresholdsFile) {
		return thresholdsFile
	}
	dir, err := os.Getwd()
	if err != nil {
		return thresholdsFile
	}
	for {
		candidate := filepath.Join(dir, thresholdsFile)
		if _, err := os.Stat(candidate); err == nil {
			return candidate
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return thresholdsFile
		}
		dir = parent
	}
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}
```

